use vstd::prelude::*;

verus! {
    // Append a value `b` to the end of vector `a`.
    // Postconditions:
    //  1) The result has length one more than `a`.
    //  2) All original elements are preserved in order.
    //  3) The last element is exactly `b`.
    fn append(a: &Vec<i32>, b: i32) -> Vec<i32>
        ensures
            result.len() == a.len() + 1,
            forall |i: usize| i < a.len() ==> result[i] == a[i],
            result[a.len()] == b,
    {
        let mut res: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        // Copy all elements of `a` into `res`
        while idx < a.len()
            invariant
                // we never overshoot the source
                idx <= a.len(),
                // we've pushed exactly `idx` elements so far
                res.len() == idx,
                // and each pushed element matches the original
                forall |j: usize| j < idx ==> res[j] == a[j],
            decreases a.len() - idx,
        {
            res.push(a[idx]);
            idx += 1;
        }
        // Now `idx == a.len()` and `res.len() == a.len()`
        // Push the new element `b`
        res.push(b);
        res
    }
}

